#!/usr/bin/env python3
"""Compare the owner-visible unsigned transactions with the exact native input."""
from pathlib import Path
from decimal import Decimal
import hashlib,json
out=Path(__file__).parent
p=Path('/Users/ravonus/dev/wt/studio-publication-20261019/keel-site/docs/reviews/studio-publication-20261019/lead/native-prerequisite-owner-review/unsigned-wallet-packet.json')
b=p.read_bytes();assert len(b)==129885 and hashlib.sha256(b).hexdigest()=='628d9615dacfd046e557821557c2b042fab1bc0e673f9c65bd887bbf9882e1db'
wallet=json.loads(b);plan=json.loads(Path('/private/tmp/keel-native49d-bounded-20261020/native481-949-prepare-01/fresh-plan.json').read_bytes());calls=plan['request']['params'][0]['blockStateCalls'][0]['calls'];assert len(wallet['transactions'])==3
rows=[];maxfee=0
for i,row in enumerate(wallet['transactions']):
    tx=row['transaction'];assert tx=={**calls[i],'chainId':'0xaa36a7'} and 'to' not in tx and tx['value']=='0x0'
    assert row['index']==i+1 and plan['expected'][i]['index']==i
    assert row['predictedAddress']==plan['expected'][i]['address'] and row['initcode']==plan['expected'][i]['initcode']
    expected=plan['expected'][i]['expectedRuntime'];assert expected['status']=='SOURCE_DERIVED_NOT_OBSERVED'
    assert row['expectedRuntime']=={k:expected[k] for k in ['bytes','sha256','keccak256']}
    maximum=int(tx['gas'],16)*int(tx['maxFeePerGas'],16);maxfee+=maximum
    rows.append({'role':row['role'],'nonce':int(tx['nonce'],16),'gasLimit':int(tx['gas'],16),'maxFeePerGasWei':int(tx['maxFeePerGas'],16),'maxPriorityFeePerGasWei':int(tx['maxPriorityFeePerGas'],16),'maximumFeeWei':str(maximum),'predictedAddress':row['predictedAddress'],'initcodeSHA256':hashlib.sha256(bytes.fromhex(tx['data'][2:])).hexdigest(),'expectedRuntime':row['expectedRuntime']})
assert wallet['chainId']==11155111 and wallet['sender']==calls[0]['from'] and wallet['totalValueWei']=='0'
assert wallet['totalMaximumFeeWeiAtExactPacketLimits']==str(maxfee)=='102279227284770'
assert Decimal(wallet['totalMaximumFeeSepoliaETH'])==Decimal(maxfee)/Decimal(10**18)
assert wallet['referenceSimulation']['freshPlanSHA256']=='6c88643d56e4e181231480b8b4090bbe53e205849987407c06266b24e667e79f' and wallet['referenceSimulation']['requestSHA256']==plan['requestSHA256'] and wallet['referenceSimulation']['canonicalHeader']==plan['header']
assert wallet['ownerApproval'] is wallet['signaturePerformed'] is wallet['submissionPerformed'] is wallet['publicationApproval'] is wallet['productionActivationApproval'] is False
review={'schema':'independent-native-prerequisite-owner-packet-review@1','decision':'APPROVE_FOR_OWNER_REVIEW_ONLY','reviewerId':'cache-release-independent-reviewer','packetSourceCommit':'211c353fdd9bb688e45e496e339bd13ed87d2d89','packetSHA256':hashlib.sha256(b).hexdigest(),'packetBytes':len(b),'nativeTerminalAuditSHA256':hashlib.sha256((out/'current-create-postrun-949-audit.json').read_bytes()).hexdigest(),'blockingFindings':[],'signingEquivalence':'Every transaction exactly equals its independently simulated call plus explicit chainId0xaa36a7; CREATE to remains omitted. Sender, nonce, gas, data, value, priority and fee unchanged. All three CREATE addresses independently recalculated with viem.','transactions':rows,'totalMaximumFeeWei':str(maxfee),'totalMaximumFeeSepoliaETH':wallet['totalMaximumFeeSepoliaETH'],'totalValueWei':'0','ownerApproval':False,'agentSigningApproved':False,'agentSubmissionApproved':False,'publicationApproved':False,'activationApproved':False,'originalGIFQualified':False,'prerequisiteScope':'Three exact Sepolia shared formatter/factory/native-media deployments only; no collection mint, user artwork upload, paid storage, publication or production activation.','requiredBeforeEachSignature':['Explicit owner approval of this exact packet, wallet on Sepolia11155111 and exact sender764E3EE7A844d9165937c41fd08086e43b997149.','Read current pending/confirmed nonce at the expected sequence296/297/298, current block gas allowance, balance for exact remaining maximum fees, sender code and each as-yet undeployed expected address; reject drift.','Confirm current fee requirement fits exact maxFee1000030wei and maxPriority1000000wei; no silent fee, gas, nonce or bytecode changes.','Wait for prior successful receipt and exact runtime readback before the next dependent transaction.'],'requiredAfterReceipts':['Receipt-backed exact formatter/factory/deployer/carriers/native-media runtime bytes and bindings, including all children, and selected-chain compatibility/registration reads.','Normal unchanged original GIF reprepare and full proof on these actual dependencies; mandatory GIF and independent release gates stay open until completed.'],'scopeClarification':'Earlier reviewer statement that no owner spend request could be offered before full GIF proof is superseded: prerequisite-only owner approval is an authorized separate stage, while production release remains blocked.','displayMetadata':'Owner indices1/2/3 map to source indices0/1/2; bytes/SHA/Keccak exact. Source status SOURCE_DERIVED_NOT_OBSERVED retained in source and actual top-level runtime observation audited separately; no actual child runtime claim.'}
p=out/'current-create-owner-packet-review.json';p.write_text(json.dumps(review,indent=2)+'\n')
print('review',len(p.read_bytes()),hashlib.sha256(p.read_bytes()).hexdigest())
